assert(underTemp(out),"Dedicated TEMP output required");let parent=out;while(!fs.existsSync(parent))parent=path.dirname(parent);assert(fs.realpathSync(parent)===temp||underTemp(fs.realpathSync(parent)),"Output symlink escapes TEMP");
