  assert.equal(await page.locator('.nav-item[data-id="schedule-adjust"],.nav-item[data-id="org-mgmt"]').count(),0);
  const allMenus=['home','workforce','sites','schedule-create','schedule-status','performance-intake','allowance-calc','proposal-export','access-history','dashboard','operations','user-mgmt'];
  const selected=option('audit-menus','').split(',').filter(Boolean),menus=selected.length?selected:allMenus;assert(menus.every(m=>allMenus.includes(m)));
  async function snapshot(name){
    await settled();
    assert.equal(await page.locator('html').getAttribute('data-theme'),'dark');
    const findings=await page.evaluate(()=>{
      const rgba=s=>{const a=s.match(/[\d.]+/g)?.map(Number)||[0,0,0,0];return[a[0],a[1],a[2],a[3]??1];};
      const blend=(fg,bg)=>fg.slice(0,3).map((v,i)=>v*fg[3]+bg[i]*(1-fg[3]));
      const lum=v=>v.map(n=>n/255).map(n=>n<=.04045?n/12.92:((n+.055)/1.055)**2.4).reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0);
      const selector=e=>e.id?'#'+e.id:e.tagName.toLowerCase()+[...e.classList].map(c=>'.'+c).join('');
      const visible=e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);if(!r.width||!r.height||r.bottom<0||r.top>innerHeight||s.visibility!=='visible'||Number(s.opacity)===0)return false;const x=Math.max(0,Math.min(innerWidth-1,r.x+r.width/2)),y=Math.max(0,Math.min(innerHeight-1,r.y+r.height/2)),hit=document.elementFromPoint(x,y);return !!hit&&(hit===e||e.contains(hit)||hit.contains(e));};
      const background=e=>{const chain=[];for(let p=e;p;p=p.parentElement)chain.push(p);let color=[255,255,255],gradient=false;for(const p of chain.reverse()){const s=getComputedStyle(p);color=blend(rgba(s.backgroundColor),color);if(s.backgroundImage!=='none'&&!s.backgroundImage.startsWith('url('))gradient=true;}return{color,gradient};};
      const paper=e=>!!e.closest('.actual-canvas-board,iframe,svg,img,.sr-only,.dashboard-sr,[aria-hidden="true"]');
      const low=[],light=[],manual=[],seen=new Set();
      for(const e of document.querySelectorAll('body *')){
        if(!(e instanceof HTMLElement)||paper(e)||!visible(e))continue;
        const s=getComputedStyle(e),r=e.getBoundingClientRect(),own=rgba(s.backgroundColor);
        if(own[3]>.9&&Math.min(...own.slice(0,3))>205&&r.width>100&&r.height>24&&r.width*r.height>2500)light.push({selector:selector(e),background:s.backgroundColor,width:Math.round(r.width),height:Math.round(r.height)});
        const input=e instanceof HTMLInputElement||e instanceof HTMLTextAreaElement||e instanceof HTMLSelectElement;
        const text=input&&e.type!=='password'&&e.value?'<입력값>':[...e.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE).map(n=>n.textContent).join('').trim();
        if(!text||!/[\p{L}\p{N}]/u.test(text)||e.closest(':disabled,[aria-disabled="true"]')||e.classList.contains('material-symbols-outlined'))continue;
        const bg=background(e),fg=blend(rgba(s.color),bg.color),a=lum(fg),b=lum(bg.color),ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05),large=parseFloat(s.fontSize)>=24||(Number(s.fontWeight)>=700&&parseFloat(s.fontSize)>=18.66),minimum=large?3:4.5,key=selector(e)+'|'+s.color+'|'+bg.color.join(',');
        if(seen.has(key))continue;seen.add(key);
        const row={selector:selector(e),ancestry:[e.parentElement,e.parentElement?.parentElement,e.parentElement?.parentElement?.parentElement].filter(Boolean).map(selector),text:text.slice(0,60),foreground:s.color,background:bg.color.map(Math.round),ratio:Number(ratio.toFixed(2)),minimum};
        if(bg.gradient)manual.push(row);else if(ratio+.01<minimum)low.push(row);
      }
      const controls=[...document.querySelectorAll('#main-content button, #main-content [role=tab], .workforce-modal-overlay button, #sites-wizard-container button')].filter(visible).map(e=>({id:e.id,name:e.getAttribute('aria-label')||e.textContent.trim().slice(0,65),class:e.className,disabled:e.disabled||false}));
      return{lowContrast:low,lightSurfaces:light,gradientReview:manual,controls,fields:[...document.querySelectorAll('#main-content input,#main-content select,.workforce-modal-overlay input,.workforce-modal-overlay select')].filter(visible).map(e=>({id:e.id,type:e.type,name:e.getAttribute('aria-label'),options:e instanceof HTMLSelectElement?[...e.options].slice(0,5).map(o=>({value:o.value,label:o.label})):undefined})),pageOverflow:document.documentElement.scrollWidth-innerWidth};
    });
    await capture('audit-'+name);states.push({name,...findings});fs.writeFileSync(path.join(out,'surface-audit-progress.json'),artifactJSON({states,totalStates:states.length},null,2));
  }
  async function tabs(prefix,exclude=''){const ids=await page.locator('#main-content [role=tab][id]').evaluateAll((nodes,exclude)=>nodes.filter(e=>!exclude||!e.closest(exclude)).map(e=>e.id),exclude);for(const id of ids){const control=page.locator('[id="'+id+'"]');if(await control.isVisible()&&!await control.isDisabled()){await control.click();await tick(page);await snapshot(prefix+'-'+id);}}}

  async function closeModal(){for(let i=0;i<6;i++){await page.keyboard.press('Escape');await settled();const overlay=page.locator('.workforce-modal-overlay');if(await overlay.count()){const cancel=overlay.last().getByRole('button',{name:/^(취소|닫기)$/});if(await cancel.count()){await cancel.last().click();await settled();}}}assert.equal(await page.locator('.workforce-modal-overlay').count(),0,'Audit must close every modal');}
  async function openModal(name,selector){const control=page.locator(selector).first();assert(await control.isVisible()&&!await control.isDisabled(),'Missing audit control: '+name+' '+selector);await control.click();await snapshot(name);const scrolls=await page.evaluate(()=>{window.__auditScrolls=[...document.querySelectorAll('.workforce-modal-body,.ops-settings-panel-content,.property-panel-content')].filter(e=>e.clientHeight>80&&e.scrollHeight>e.clientHeight+40);return window.__auditScrolls.length;});for(let i=0;i<Math.min(3,scrolls);i++){await page.evaluate(i=>window.__auditScrolls[i].scrollTop=window.__auditScrolls[i].scrollHeight,i);await snapshot(name+'-scroll-'+i);}await closeModal();}
  await theme('dark');
  for(const menu of menus){
    await nav(menu);await page.waitForLoadState('networkidle');await snapshot(menu);
    if(menu==='operations')for(const id of['settings','holidays','rates','users','layout','site-names','releases']){await tab(id);await snapshot('operations-'+id);await tabs('operations-'+id,'.operations-tab-list');}
    else await tabs(menu);
    if(menu==='workforce')for(const [name,id]of [['new','#btn-e1-new'],['edit','#btn-edit-employee'],['wage','#btn-open-e3'],['assignment','#btn-open-e4'],['reorder','#btn-open-e5'],['bulk-wage','#btn-open-e6']])await openModal('workforce-'+name,id);
    if(menu==='sites'){
      const edit=page.getByRole('button',{name:'이 버전 수정',exact:true}).first();assert(await edit.isVisible());await edit.click();await snapshot('sites-wizard-basics');await openModal('sites-copy','#btn-open-site-copy');for(let i=0;i<3;i++){const next=page.locator('#btn-wizard-next');assert(await next.isVisible()&&!await next.isDisabled());await next.click();await snapshot('sites-wizard-next-'+i);if(i===0){for(const [name,id]of [['pattern-details','#btn-pattern-details'],['exceptions','#btn-pattern-exceptions'],['guide','#btn-pattern-guide'],['import','#btn-open-import-modal']])await openModal('sites-'+name,id);await page.locator('#btn-holiday-policy').click();await snapshot('sites-holiday-default');await page.locator('input[data-category="public"]').check();await snapshot('sites-holiday-normal');await page.locator('input[name="holiday-mode"][value="separate"]').check();await snapshot('sites-holiday-separate');await page.locator('input[name="holiday-mode"][value="off"]').check();await snapshot('sites-holiday-off');await closeModal();}}await page.locator('#btn-wizard-cancel').click();if(await page.locator('#btn-confirm-ok').isVisible())await page.locator('#btn-confirm-ok').click();await settled();
    }
    if(menu==='schedule-create'||menu==='schedule-status'){await page.locator('#tab-btn-calendar').click();await settled();await openModal(menu+'-day-detail','.schedule-month-day[data-date]');await page.locator('#btn-schedule-reading').click();await snapshot(menu+'-large-calendar');await page.keyboard.press('Escape');await settled();}
    if(menu==='performance-intake'){await openModal('performance-intake-history','#btn-perf-history');await openModal('performance-intake-status','#btn-perf-intake-status');}
    if(menu==='proposal-export')for(let i=0;i<4;i++){await page.locator('.allowance-tab-btn').nth(i).click();await snapshot('allowance-history-tab-'+i);if(i===3){const buttons=await page.locator('button[data-history-detail]').count();assert(buttons>=2,'Actual proposal/export fixtures required');for(let j=0;j<2;j++)await openModal('allowance-history-detail-'+j,'button[data-history-detail] >> nth='+j);}}
    if(menu==='operations'){
      await tab('settings');await page.locator('#btn-settings-area-policy').click();await openModal('operations-policy-history','#btn-open-substitute-policy');
      await page.locator('#btn-open-substitute-policy').click();await page.locator('#btn-add-new-policy').click();await snapshot('operations-policy-new-version');await closeModal();
      await tab('holidays');await page.locator('#holiday-area-calendar').click();await openModal('operations-holiday-add','#btn-add-holiday');
      await tab('users');await page.locator('#ops-users-area-users').click();await openModal('operations-user-edit','.users-table-wrap tr.table-row button');
    }

  }
  if(!selected.length){await page.locator('.btn-logout').click();await page.locator('#login-id').waitFor();await snapshot('login');}
  const lowContrast=states.reduce((n,s)=>n+s.lowContrast.length,0),lightSurfaces=states.reduce((n,s)=>n+s.lightSurfaces.length,0),gradientReview=states.reduce((n,s)=>n+s.gradientReview.length,0),overflow=states.filter(s=>s.pageOverflow>1),required=['sites-wizard-basics','sites-wizard-next-0','sites-wizard-next-1','sites-wizard-next-2','sites-pattern-details','sites-exceptions','sites-holiday-normal','sites-holiday-separate','sites-holiday-off','schedule-create-day-detail','schedule-create-large-calendar','schedule-status-day-detail','schedule-status-large-calendar','performance-intake-history','allowance-history-tab-3','allowance-history-detail-0','allowance-history-detail-1','operations-holiday-add','operations-user-edit','login'];
